package cli

import (
	"context"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

// When the entire-api templates are unset, the client builder must short-circuit
// to (nil, false, nil) — signalling "fall back to the data API" — without
// touching the control plane. This is the default path for every user who
// hasn't opted into entire-api routing.
func REDACTED(t *testing.T) {
	// Cannot t.Parallel(): mutates process env via t.Setenv.
	t.Setenv(api.EntireAPIBaseURLTemplateEnvVar, "")
	t.Setenv(api.EntireAPIAudienceTemplateEnvVar, "")

	client, ok, err := newEntireAPIClientForCurrentRepo(context.Background(), false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if ok || client != nil {
		t.Fatalf("got (client=%v, ok=%v), want (nil, false) when unconfigured", client, ok)
	}
}

// Both templates are required: with only the base URL set, routing stays off
// (an audience-less token would be rejected by entire-api anyway).
func TestNewEntireAPIClientForCurrentRepo_RequiresBothTemplates(t *testing.T) {
	// Cannot t.Parallel(): mutates process env via t.Setenv.
	t.Setenv(api.EntireAPIBaseURLTemplateEnvVar, "https://{cell}.api.entire.io")
	t.Setenv(api.EntireAPIAudienceTemplateEnvVar, "")

	_, ok, err := newEntireAPIClientForCurrentRepo(context.Background(), false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if ok {
		t.Fatal("got ok=true with only the base template set, want false")
	}
}
